// ===== Algebra I (rest) =====
addUnits("a1",[["a1ineq","Inequalities"],["a1fn","Functions & Rates of Change"],["a1seq","Sequences & Exponential Functions"],["a1poly","Polynomials & Factoring"],["a1quad","Quadratic Functions & Equations"],["a1rad","Radicals & Real Numbers"],["a1stat","Statistics & Data"]]);
const bf=(m,p)=>"("+lin(m,p)+")";
const rparts=n=>{let k=1,m=n;for(let f=2;f*f<=m;f++)while(m%(f*f)===0){m/=f*f;k*=f}return [k,m]};
const rs=(c,n)=>{const [k,m]=rparts(n);const cc=c*k;return m===1?String(cc):(cc===1?"":cc===-1?"-":cc)+"sqrt("+m+")"};
const cmpSym={"<":"<",">":">","<=":"≤",">=":"≥"};
const flip=o=>({"<":">",">":"<","<=":">=",">=":"<="}[o]);
const IVL=(a,ac,b,bc)=>`${ac?"[":"("}${a}, ${b}${bc?"]":")"}`;
T("abs-eq","a1eq","A.REI.3","Absolute value equations",["multistep-eq","abs-opp"],
 "The equation |A| = r asks for numbers whose distance from 0 is r, so A = r or A = −r. Solve both equations.",
 ["Isolate the absolute value first: |x| + 3 = 8 → |x| = 5.","Split: |A| = r (r > 0) means A = r or A = −r. Two solutions are possible.","|A| = negative number has no solution; type none."],
 [()=>{const q=rnz(-9,9),r=ri(1,9);return mk("set",`Solve: |x + ${q}| = ${r}`.replace("+ -","- "),`${-q+r}, ${-q-r}`,"Split into x + q = r and x + q = −r.",`x ${q<0?"-":"+"} ${Math.abs(q)} = ${r} → x = ${-q+r}; x ${q<0?"-":"+"} ${Math.abs(q)} = ${-r} → x = ${-q-r}`,{fx:`Math.abs(x+(${q}))-${r}`,nroots:2})},
  ()=>{const a=ri(2,4),x1=ri(-3,6),d=ri(1,4);const b=-a*(x1-d),r=a*d;return mk("set",`Solve: |${lin(a,b)}| = ${r}`,`${x1}, ${x1-2*d}`,"Write ax + b = r and ax + b = −r.",`${lin(a,b)} = ${r} → x = ${x1}; ${lin(a,b)} = ${-r} → x = ${x1-2*d}`,{fx:`Math.abs(${a}*x+(${b}))-${r}`,nroots:2})},
  ()=>{const c=ri(1,9),d=c+ri(1,9);return mk("set",`Solve: |x| + ${c} = ${d}`,`${-(d-c)}, ${d-c}`,"Isolate |x| first, then split.",`|x| = ${d} − ${c} = ${d-c}, so x = ±${d-c}`,{fx:`Math.abs(x)+${c}-${d}`,nroots:2})},
  ()=>{const q=rnz(-8,8),k=ri(1,9);return mk("set",`Solve: |x + ${q}| = -${k}`.replace("+ -","- "),"none","An absolute value can never be negative.",`|anything| ≥ 0, so |x ${q<0?"−":"+"} ${Math.abs(q)}| = −${k} has no solution`,{fx:`Math.abs(x+(${q}))+${k}`})}]);
T("ineq-multi","a1ineq","A.REI.3","Multi-step inequalities",["ineq","multistep-eq"],
 "Solve inequalities like equations, with one big rule: when you multiply or divide both sides by a negative number, the inequality sign flips.",
 ["Collect variable terms on one side and constants on the other.","Multiplying/dividing by a negative reverses the sign: −2x > 6 → x < −3.","Answer like x > 3 or x <= -2."],
 [()=>{let a,c;do{a=ri(-6,7);c=ri(-6,7)}while(a===c);const n=rnz(-8,8),b=ri(-9,9),d=(a-c)*n+b;const op=pick(["<",">","<=",">="]);const ans=(a-c)>0?op:flip(op);return mk("ineq",`Solve: ${lin(a,b)} ${op} ${lin(c,d)}`,`x ${ans} ${n}`,"Collect x terms on one side; flip the sign if you divide by a negative.",`${a-c}x ${op} ${d-b} → x ${ans} ${n}${(a-c)<0?" (divided by a negative, so the sign flips)":""}`,{ineq:`${a}*x+(${b})${op}${c}*x+(${d})`})},
  ()=>{const a=rnz(-5,5),n=rnz(-8,8),q=rnz(-6,6),r=a*(n+q);const op=pick(["<",">","<=",">="]);const ans=a>0?op:flip(op);return mk("ineq",`Solve: ${a}(x + ${q}) ${op} ${r}`.replace("+ -","- "),`x ${ans} ${n}`,"Distribute, isolate x, and flip the sign when dividing by a negative.",`${a}x + ${a*q} ${op} ${r} → ${a}x ${op} ${r-a*q} → x ${ans} ${n}`,{ineq:`${a}*(x+(${q}))${op}${r}`})},
  ()=>{const a=ri(2,7),b=ri(-9,9),n=rnz(-8,8),c=-a*n+b;const op=pick(["<",">","<=",">="]);const ans=flip(op);return mk("ineq",`Solve: ${polyStr([[-a,"x"],[b,""]])} ${op} ${c}`,`x ${ans} ${n}`,"Subtract b, then divide by the negative coefficient and flip the sign.",`${-a}x ${op} ${c-b} → x ${ans} ${n}`,{ineq:`-${a}*x+(${b})${op}${c}`})},
  ()=>{const k=ri(2,6),b=ri(-8,8),m=rnz(-6,6),n=k*m;const c=-n/k+b;const op=pick(["<",">","<=",">="]);return mk("ineq",`Solve: -x/${k} + ${b} ${op} ${c}`.replace("+ -","- "),`x ${flip(op)} ${n}`,"Move the constant, then multiply by −k (flip the sign).",`-x/${k} ${op} ${c-b} → x ${flip(op)} ${-k*(c-b)}`,{ineq:`-x/${k}+(${b})${op}${c}`})}]);
T("compound-ineq","a1ineq","A.REI.3","Compound inequalities",["ineq-multi"],
 "A compound inequality joins two inequalities. 'And' (a double inequality) is the overlap; 'or' is the union. Write answers in interval notation.",
 ["L < ax + b < U: do the same operation to all three parts. Dividing by a negative flips both signs and swaps the ends.","Interval notation: ( ) for strict, [ ] for inclusive; use inf for ∞. Type (-2, 4].","x < p or x > q gives (-inf, p) U (q, inf)."],
 [()=>{const a=ri(2,5),b=ri(-6,6),x1=ri(-6,2),x2=x1+ri(2,7),s1=Math.random()<0.5,s2=Math.random()<0.5;const L=a*x1+b,U=a*x2+b;return mk("interval",`Solve and write in interval notation: ${L} ${s1?"<":"<="} ${lin(a,b)} ${s2?"<":"<="} ${U}`,IVL(x1,!s1,x2,!s2),"Subtract b from all three parts, then divide by a.",`${L-b} ${s1?"<":"≤"} ${a}x ${s2?"<":"≤"} ${U-b} → ${x1} ${s1?"<":"≤"} x ${s2?"<":"≤"} ${x2}`,{inside:`(x${s1?">":">="}${x1})&&(x${s2?"<":"<="}${x2})`})},
  ()=>{const a=-ri(2,5),b=ri(-6,6),x1=ri(-6,2),x2=x1+ri(2,6),s=Math.random()<0.5;const L=a*x2+b,U=a*x1+b;return mk("interval",`Solve and write in interval notation: ${L} ${s?"<":"<="} ${lin(a,b)} ${s?"<":"<="} ${U}`,IVL(x1,!s,x2,!s),"Divide by the negative coefficient: the inequality signs reverse, so reverse the order of the ends.",`${L-b} ${s?"<":"≤"} ${a}x ${s?"<":"≤"} ${U-b} → ${x1} ${s?"<":"≤"} x ${s?"<":"≤"} ${x2}`,{inside:`(x${s?">":">="}${x1})&&(x${s?"<":"<="}${x2})`})},
  ()=>{const p=ri(-6,2),q=p+ri(2,8),b1=ri(-5,5),a2=ri(2,4),b2=ri(-5,5);return mk("interval",`Solve and write in interval notation: x + ${b1} < ${p+b1} or ${a2}x + ${b2} > ${a2*q+b2}`.replace("+ -","- "),`(-inf, ${p}) U (${q}, inf)`,"Solve each inequality separately; 'or' means the union.",`x < ${p} or x > ${q}`,{inside:`(x<${p})||(x>${q})`})}]);
T("lin-ineq2","a1ineq","A.REI.12","Linear inequalities in two variables",["ineq-multi","lin-graph"],
 "The solutions of y > mx + b form a half-plane. The boundary line is dashed for < and > and solid for ≤ and ≥; test a point to decide which side to shade.",
 ["Boundary: replace the inequality sign with =. Solid line if ≤ or ≥; dashed if < or >.","Shade above the line for y > or y ≥; below for y < or y ≤ (after solving for y).","Dividing by a negative number flips the inequality when solving for y."],
 [()=>{const m=rnz(-4,4),b=ri(-6,6),px=ri(-5,5);let py=ri(-8,8);if(py===m*px+b)py++;const op=pick(["<",">"]);const yes=op===">"?py>m*px+b:py<m*px+b;return mcq(`Is (${px}, ${py}) a solution of y ${op} ${lin(m,b)}?`,yes?"Yes":"No",[yes?"No":"Yes"],"Substitute the point and see whether the inequality is true.",`${py} ${op} ${m}(${px}) + ${b} = ${m*px+b}? ${yes?"True":"False"}`,{js:`(${py}${op}${m*px+b})===${yes}`})},
  ()=>{const op=pick(["<",">","<=",">="]),m=rnz(-4,4),b=ri(-6,6);const ans=op.length===2?"Solid":"Dashed";return mcq(`Is the boundary line of y ${op} ${lin(m,b)} solid or dashed?`,ans,[ans==="Solid"?"Dashed":"Solid"],"≤ and ≥ include the line (solid); < and > do not (dashed).",`The sign is ${cmpSym[op]}, so the line is ${ans.toLowerCase()}.`)},
  ()=>{const A=rnz(-5,5),B=rnz(-5,5),C=ri(-9,9),op=pick(["<",">","<=",">="]);const eff=B>0?op:flip(op);const ans=eff[0]===">"?"Above the line":"Below the line";return mcq(`The solution of ${polyStr([[A,"x"],[B,"y"]])} ${op} ${C} is shaded. Is the shading above or below the boundary line (in the usual y-up graph)?`,ans,[ans==="Above the line"?"Below the line":"Above the line"],"Solve for y; dividing by a negative coefficient of y flips the sign.",`y ${cmpSym[eff]} ... so shade ${ans.toLowerCase()}`)},
  ()=>{const m1=rnz(-3,3),b1=ri(-5,5),m2=rnz(-3,3),b2=ri(-5,5);const px=ri(-5,5);let py=ri(-8,8);if(py===m1*px+b1||py===m2*px+b2)py+=7;const o1=pick(["<",">"]),o2=pick(["<",">"]);const t1=o1===">"?py>m1*px+b1:py<m1*px+b1,t2=o2===">"?py>m2*px+b2:py<m2*px+b2;const yes=t1&&t2;return mcq(`Is (${px}, ${py}) a solution of the system y ${o1} ${lin(m1,b1)} and y ${o2} ${lin(m2,b2)}?`,yes?"Yes":"No",[yes?"No":"Yes"],"A point solves a system only if it satisfies every inequality.",`1st: ${py} ${o1} ${m1*px+b1} is ${t1}; 2nd: ${py} ${o2} ${m2*px+b2} is ${t2}`,{js:`((${py}${o1}${m1*px+b1})&&(${py}${o2}${m2*px+b2}))===${yes}`})}]);
T("point-slope","a1lin","A.CED.2","Point-slope & standard form",["slope-int"],
 "A line can be written several ways: slope-intercept y = mx + b, point-slope y − y₁ = m(x − x₁), and standard form Ax + By = C. Any equivalent form is accepted.",
 ["Point-slope: through (x₁, y₁) with slope m: y − y₁ = m(x − x₁).","Two points: slope m = (y₂ − y₁)/(x₂ − x₁), then use either point.","Standard form: clear fractions so A, B, C are integers: 2x + 3y = 6."],
 [()=>{const m=rnz(-5,5),x1=rnz(-6,6),y1=rnz(-6,6);return mk("eq",`Write an equation of the line through (${x1}, ${y1}) with slope ${m}.`,`y ${y1<0?"+":"-"} ${Math.abs(y1)} = ${m}(x ${x1<0?"+":"-"} ${Math.abs(x1)})`,"Point-slope form: y − y₁ = m(x − x₁).",`y − ${P(y1)} = ${m}(x − ${P(x1)})`,{pe:`y-(${y1})-(${m})*(x-(${x1}))`})},
  ()=>{const m=rnz(-4,4),b=ri(-8,8),x1=ri(-4,2),x2=x1+ri(1,4);const y1=m*x1+b,y2=m*x2+b;return mk("eq",`Write the equation of the line through (${x1}, ${y1}) and (${x2}, ${y2}) in slope-intercept form.`,siStr(m,1,b,1),"Find the slope, then solve for b with one point.",`m = (${y2} − ${P(y1)})/(${x2} − ${P(x1)}) = ${m}; b = ${y1} − ${m}(${x1}) = ${b}`,{pe:`y-(${m}*x+(${b}))`})},
  ()=>{let p,q;do{p=rnz(-5,5);q=ri(2,5)}while(gcd(p,q)!==1);const r=ri(-5,5);return mk("eq",`Write y = (${p}/${q})x ${r<0?"-":"+"} ${Math.abs(r)} in standard form Ax + By = C with integer coefficients.`,`${polyStr([[-p,"x"],[q,"y"]])} = ${q*r}`,"Multiply every term by the denominator, then move the x term to the left.",`${q}y = ${p}x + ${q*r} → ${polyStr([[-p,"x"],[q,"y"]])} = ${q*r}`,{pe:`${-p}*x+${q}*y-${q*r}`})},
  ()=>{const m=rnz(-5,5),x1=ri(-5,5),y1=ri(-8,8);return mk("num",`Find the x-intercept of the line through (${x1}, ${y1}) with slope ${m}.`,frs(m*x1-y1,m),"Write the equation, set y = 0 and solve for x.",`y − ${P(y1)} = ${m}(x − ${P(x1)}); set y = 0 → x = ${frs(m*x1-y1,m)}`,{js:`${x1}-(${y1})/(${m})`})}]);
T("parallel-perp","a1lin","G.GPE.5","Parallel & perpendicular lines",["point-slope"],
 "Parallel lines have equal slopes. Perpendicular lines have slopes that are negative reciprocals (their product is −1).",
 ["Parallel: m₁ = m₂.   Perpendicular: m₂ = −1/m₁.","To write the line through a point, use the new slope and the point.","From Ax + By = C the slope is −A/B."],
 [()=>{const A=rnz(-6,6),B=rnz(-6,6),C=ri(-9,9);return mk("num",`Find the slope of any line parallel to ${polyStr([[A,"x"],[B,"y"]])} = ${C}.`,frs(-A,B),"Parallel lines share the same slope: −A/B.",`slope = −(${A})/(${B}) = ${frs(-A,B)}`,{js:`-(${A})/(${B})`})},
  ()=>{const p=rnz(-7,7),q=ri(1,6);return mk("num",`A line has slope ${frs(p,q)}. What is the slope of a line perpendicular to it?`,frs(-q,p),"Take the negative reciprocal.",`−1 ÷ (${frs(p,q)}) = ${frs(-q,p)}`,{js:`-1/(${p}/${q})`})},
  ()=>{const m=rnz(-5,5),b=ri(-8,8),x1=ri(-5,5),y1=ri(-8,8);return mk("eq",`Write the equation of the line through (${x1}, ${y1}) that is parallel to y = ${lin(m,b)}.`,siStr(m,1,y1-m*x1,1),"Use the same slope and solve for the new intercept.",`b = ${y1} − ${m}(${x1}) = ${y1-m*x1}`,{pe:`y-(${m}*x+(${y1-m*x1}))`})},
  ()=>{const k=rnz(-5,5),b=ri(-8,8),x1=ri(-5,5),y1=ri(-8,8);return mk("eq",`Write the equation of the line through (${x1}, ${y1}) that is perpendicular to y = (${frs(-1,k)})x ${b<0?"-":"+"} ${Math.abs(b)}.`,siStr(k,1,y1-k*x1,1),"The perpendicular slope is the negative reciprocal; then solve for b.",`slope = ${k}; b = ${y1} − ${k}(${x1}) = ${y1-k*x1}`,{pe:`y-(${k}*x+(${y1-k*x1}))`})}]);
T("domain-range","a1fn","F.IF.5","Domain & range",["func-eval","ineq-multi"],
 "The domain is the set of allowed inputs; the range is the set of outputs. Square roots need non-negative insides and denominators can't be 0.",
 ["√(expression): the expression must be ≥ 0.   1/(expression): the expression must not be 0.","Range of x² + c: y ≥ c (the vertex is the lowest point); of −x² + c: y ≤ c.","Write intervals like [2, inf) or (-inf, 3) U (3, inf)."],
 [()=>{const a=rnz(-8,8);return mk("interval",`Find the domain of f(x) = sqrt(x ${a<0?"+":"-"} ${Math.abs(a)}).`,`[${a}, inf)`,"The radicand must be at least 0.",`x ${a<0?"+":"-"} ${Math.abs(a)} ≥ 0 → x ≥ ${a}`,{inside:`x>=${a}`})},
  ()=>{const a=rnz(-8,8);return mk("interval",`Find the domain of f(x) = 1/(x ${a<0?"+":"-"} ${Math.abs(a)}).`,`(-inf, ${a}) U (${a}, inf)`,"The denominator cannot be 0.",`x ${a<0?"+":"-"} ${Math.abs(a)} ≠ 0 → x ≠ ${a}`,{inside:`x!==${a}`})},
  ()=>{const c=rnz(-9,9),neg=Math.random()<0.5;return mk("interval",`Find the range of f(x) = ${neg?"-":""}x^2 ${c<0?"-":"+"} ${Math.abs(c)}.`,neg?`(-inf, ${c}]`:`[${c}, inf)`,neg?"An upside-down parabola's vertex is its highest point.":"A parabola opening up has its vertex as the lowest point.",`vertex at (0, ${c}); ${neg?"y ≤":"y ≥"} ${c}`,{inside:neg?`x<=${c}`:`x>=${c}`})},
  ()=>{const a=rnz(-8,8);return mk("interval",`Find the domain of f(x) = sqrt(${a} - x).`,`(-inf, ${a}]`,"The radicand must be at least 0; solving flips the sign.",`${a} − x ≥ 0 → x ≤ ${a}`,{inside:`x<=${a}`})}]);
T("fn-ops","a1fn","F.BF.1","Combining functions",["func-eval","poly-add"],
 "Functions can be added, subtracted and multiplied like expressions: (f + g)(x) = f(x) + g(x), (f·g)(x) = f(x)·g(x).",
 ["(f + g)(x) = f(x) + g(x);  (f − g)(x) = f(x) − g(x) (distribute the minus).","(f · g)(x) = f(x) · g(x): multiply and combine like terms.","To evaluate (f + g)(k), find f(k) and g(k) and add."],
 [()=>{const a=ri(-5,5),b=ri(-6,6),c=rnz(-4,4),d=ri(-5,5),e=ri(-6,6);return mk("poly",`If f(x) = ${lin(a,b)} and g(x) = ${quad(c,d,e)}, find (f + g)(x).`,quad(c,a+d,b+e),"Add the two expressions and combine like terms.",`${c}x² + (${a}+${P(d)})x + (${b}+${P(e)})`,{pe:`(${a}*x+${b})+(${c}*x*x+${d}*x+${e})`})},
  ()=>{const a=ri(-5,5),b=ri(-6,6),c=rnz(-4,4),d=ri(-5,5),e=ri(-6,6);return mk("poly",`If f(x) = ${lin(a,b)} and g(x) = ${quad(c,d,e)}, find (g − f)(x).`,quad(c,d-a,e-b),"Subtract f(x) from g(x): change every sign of f(x).",`${c}x² + (${d}−${P(a)})x + (${e}−${P(b)})`,{pe:`(${c}*x*x+${d}*x+${e})-(${a}*x+${b})`})},
  ()=>{const a=rnz(-4,4),b=rnz(-6,6),c=rnz(-4,4),d=rnz(-6,6);return mk("poly",`If f(x) = ${lin(a,b)} and g(x) = ${lin(c,d)}, find (f · g)(x).`,quad(a*c,a*d+b*c,b*d),"Multiply the binomials (FOIL) and combine like terms.",`${a*c}x² + (${a*d}+${b*c})x + ${b*d}`,{pe:`(${a}*x+${b})*(${c}*x+${d})`})},
  ()=>{const a=rnz(-4,4),b=ri(-6,6),c=rnz(-3,3),d=ri(-5,5),e=ri(-6,6),k=ri(-4,4);return mk("num",`If f(x) = ${lin(a,b)} and g(x) = ${quad(c,d,e)}, find (f + g)(${k}).`,a*k+b+c*k*k+d*k+e,"Evaluate f(k) and g(k), then add.",`f(${k}) = ${a*k+b}; g(${k}) = ${c*k*k+d*k+e}`,{js:`(${a}*(${k})+(${b}))+(${c}*(${k})**2+${d}*(${k})+(${e}))`})}]);
T("avg-rate","a1fn","F.IF.6","Average rate of change",["func-eval","slope"],
 "The average rate of change of f from x = a to x = b is the slope of the line between the two points: (f(b) − f(a)) / (b − a).",
 ["Evaluate f at both ends of the interval.","Divide the change in output by the change in input.","In context it is a rate: miles per hour, dollars per year, ..."],
 [()=>{const a=rnz(-3,3),b=ri(-6,6),c=ri(-8,8),x1=ri(-3,1),x2=x1+ri(1,4);const f=x=>a*x*x+b*x+c;return mk("num",`Find the average rate of change of f(x) = ${quad(a,b,c)} from x = ${x1} to x = ${x2}.`,frs(f(x2)-f(x1),x2-x1),"(f(b) − f(a)) ÷ (b − a).",`f(${x1}) = ${f(x1)}, f(${x2}) = ${f(x2)}; ${f(x2)-f(x1)}/${x2-x1}`,{js:`(${a}*(${x2})**2+${b}*(${x2})+${c}-(${a}*(${x1})**2+${b}*(${x1})+${c}))/((${x2})-(${x1}))`})},
  ()=>{const xs=[0,2,4,6],ys=[ri(0,20)];for(let i=1;i<4;i++)ys.push(ys[i-1]+ri(-5,15));const i1=ri(0,1),i2=ri(2,3);return mk("num",`A table gives f(${xs[0]}) = ${ys[0]}, f(${xs[1]}) = ${ys[1]}, f(${xs[2]}) = ${ys[2]}, f(${xs[3]}) = ${ys[3]}. Find the average rate of change from x = ${xs[i1]} to x = ${xs[i2]}.`,frs(ys[i2]-ys[i1],xs[i2]-xs[i1]),"Change in f ÷ change in x.",`(${ys[i2]} − ${P(ys[i1])})/(${xs[i2]} − ${xs[i1]})`,{js:`(${ys[i2]}-(${ys[i1]}))/(${xs[i2]}-${xs[i1]})`})},
  ()=>{const a=ri(1,5),b=ri(2,4),x2=ri(2,4);const f=x=>a*Math.pow(b,x);return mk("num",`Find the average rate of change of f(x) = ${a}·${b}^x from x = 0 to x = ${x2}.`,frs(f(x2)-f(0),x2),"(f(b) − f(a)) ÷ (b − a).",`f(0) = ${a}, f(${x2}) = ${f(x2)}; ${f(x2)-a}/${x2}`,{js:`(${a}*${b}**${x2}-${a})/${x2}`})},
  ()=>{const t1=ri(1,3),t2=t1+ri(2,4),v=ri(20,60),d1=ri(10,80);return mk("num",`A car is ${d1} miles from home after ${t1} hours and ${d1+v*(t2-t1)} miles from home after ${t2} hours. What is its average speed (mph)?`,v,"Average speed = change in distance ÷ change in time.",`(${d1+v*(t2-t1)} − ${d1})/(${t2} − ${t1}) = ${v}`,{js:`(${d1+v*(t2-t1)}-${d1})/(${t2}-${t1})`})}]);
T("piecewise-abs","a1fn","F.IF.7b","Piecewise & absolute value functions",["func-eval","abs-eq"],
 "A piecewise function uses different rules on different parts of its domain. The absolute value function y = a|x − h| + k is V-shaped with its vertex at (h, k).",
 ["Pick the rule whose condition the input satisfies, then evaluate it.","y = a|x − h| + k: vertex (h, k); a < 0 opens downward.","Evaluate |ax + b| by computing the inside first, then dropping the sign."],
 [()=>{const a=rnz(-3,3),b=ri(-5,5),c=ri(-2,3),d=rnz(-3,3),e=ri(-6,6),x=ri(-4,6);const v=x<c?a*x+b:d*x+e;return mk("num",`f(x) = ${lin(a,b)} if x < ${c}; f(x) = ${lin(d,e)} if x ≥ ${c}. Find f(${x}).`,v,"Choose the rule that matches x, then evaluate.",`${x} ${x<c?"<":"≥"} ${c}, so use ${x<c?lin(a,b):lin(d,e)}: ${v}`,{js:`${x}<${c}?${a}*${x}+${b}:${d}*${x}+${e}`})},
  ()=>{const a=rnz(-3,3),b=ri(-8,8),c=ri(-6,6),x=ri(-6,6);return mk("num",`Evaluate f(x) = |${lin(a,b)}| ${c<0?"-":"+"} ${Math.abs(c)} at x = ${x}.`,Math.abs(a*x+b)+c,"Compute the inside, take the absolute value, then add.",`|${a}(${x}) + ${b}| + ${c} = |${a*x+b}| + ${c} = ${Math.abs(a*x+b)+c}`,{js:`Math.abs(${a}*${x}+(${b}))+(${c})`})},
  ()=>{const a=pick([1,2,3,-1,-2]),h=rnz(-6,6),k=rnz(-6,6);return mk("pair",`Find the vertex of y = ${a===1?"":a===-1?"-":a}|x ${h<0?"+":"-"} ${Math.abs(h)}| ${k<0?"-":"+"} ${Math.abs(k)}.`,`(${h}, ${k})`,"For y = a|x − h| + k the vertex is (h, k).",`h = ${h}, k = ${k}`,{eqs:[`x=${h}`,`y=${k}`]})}]);
T("seq-arith","a1seq","F.BF.2","Arithmetic sequences",["func-eval","slope"],
 "In an arithmetic sequence each term is found by adding the same number d (the common difference).",
 ["Explicit formula: aₙ = a₁ + (n − 1)d.   Recursive: aₙ = aₙ₋₁ + d.","d = any term minus the term before it.","To find which term equals a value L, solve a₁ + (n − 1)d = L."],
 [()=>{const a=ri(-10,20),d=rnz(-6,8),n=ri(6,20);return mk("num",`An arithmetic sequence has first term ${a} and common difference ${d}. Find term number ${n}.`,a+(n-1)*d,"aₙ = a₁ + (n − 1)d.",`${a} + (${n}−1)(${d}) = ${a+(n-1)*d}`,{js:`${a}+(${n}-1)*(${d})`})},
  ()=>{const a=ri(-8,15),d=rnz(-6,7);const t=[0,1,2,3].map(i=>a+i*d).join(", ");return mk("expr",`Write an explicit formula for the nth term of the arithmetic sequence ${t}, … (use the letter n).`,polyStr([[d,"n"],[a-d,""]]),"aₙ = a₁ + (n − 1)d, then simplify.",`${a} + (n−1)(${d}) = ${polyStr([[d,"n"],[a-d,""]])}`,{vars:["n"],pe:`${d}*n+(${a-d})`})},
  ()=>{const a=ri(-10,10),d=rnz(-6,6),n=ri(8,25);const L=a+(n-1)*d;return mk("num",`In the arithmetic sequence ${a}, ${a+d}, ${a+2*d}, …, which term number equals ${L}?`,n,"Solve a₁ + (n − 1)d = L for n.",`${a} + (n−1)(${d}) = ${L} → n − 1 = ${(L-a)/d} → n = ${n}`,{eqs:[`${a}+(x-1)*(${d})=${L}`]})},
  ()=>{const a=ri(-10,10),d=rnz(-7,7),p=ri(2,5),q=p+ri(2,5);return mk("num",`In an arithmetic sequence, term number ${p} is ${a+(p-1)*d} and term number ${q} is ${a+(q-1)*d}. Find the common difference.`,d,"d = (difference in terms) ÷ (difference in positions).",`(${a+(q-1)*d} − ${P(a+(p-1)*d)})/(${q} − ${p}) = ${d}`,{js:`(${a+(q-1)*d}-(${a+(p-1)*d}))/(${q}-${p})`})},
  ()=>{const a=ri(-5,10),d=rnz(-5,6),n=ri(5,8);return mk("num",`A sequence starts at ${a}, and each term is the previous term ${d<0?"minus":"plus"} ${Math.abs(d)}. Find term number ${n}.`,a+(n-1)*d,"Apply the recursive rule repeatedly (adding d each step).",`term ${n} = ${a} + ${n-1}(${d}) = ${a+(n-1)*d}`,{js:`${a}+${n-1}*(${d})`})}]);
T("seq-geo","a1seq","F.BF.2","Geometric sequences",["seq-arith","exp-neg-zero"],
 "In a geometric sequence each term is found by multiplying by the same number r (the common ratio).",
 ["Explicit formula: aₙ = a₁ · rⁿ⁻¹.   Recursive: aₙ = r · aₙ₋₁.","r = any term ÷ the term before it.","Ratios can be fractions or negative."],
 [()=>{const a=ri(1,6),r=pick([2,3,-2,-3,4]),n=ri(4,7);return mk("num",`A geometric sequence has first term ${a} and common ratio ${r}. Find term number ${n}.`,a*Math.pow(r,n-1),"aₙ = a₁ · rⁿ⁻¹.",`${a} × ${P(r)}^${n-1} = ${a*Math.pow(r,n-1)}`,{js:`${a}*(${r})**${n-1}`})},
  ()=>{const a=ri(1,6),r=pick([2,3,4,5,-2,-3]);return mk("num",`What is the common ratio of the geometric sequence ${a}, ${a*r}, ${a*r*r}, ${a*r*r*r}, …?`,r,"r = a term ÷ the previous term.",`${a*r} ÷ ${a} = ${r}`,{js:`${a*r*r}/${a*r}`})},
  ()=>{const a=ri(1,7),r=pick([2,3,4,5]);return mk("expr",`Write an explicit formula for the nth term of the geometric sequence ${a}, ${a*r}, ${a*r*r}, … (use the letter n).`,`${a}(${r})^(n-1)`,"aₙ = a₁ · rⁿ⁻¹.",`aₙ = ${a}(${r})^(n−1)`,{vars:["n"],pe:`${a}*${r}**(n-1)`})},
  ()=>{const k=ri(5,8),a=Math.pow(2,k);const n=ri(4,k+1);return mk("num",`A geometric sequence starts ${a}, ${a/2}, ${a/4}, … Find term number ${n}.`,frs(a,Math.pow(2,n-1)),"r = 1/2; aₙ = a₁ rⁿ⁻¹.",`${a} × (1/2)^${n-1} = ${frs(a,Math.pow(2,n-1))}`,{js:`${a}*0.5**${n-1}`})}]);
T("exp-growth","a1seq","F.LE.2","Exponential growth & decay",["seq-geo","percent"],
 "An exponential function f(t) = a·bᵗ multiplies by the growth factor b for each unit of time. Growth: b > 1; decay: 0 < b < 1.",
 ["Percent growth r: b = 1 + r (5% → 1.05). Percent decay r: b = 1 − r (20% → 0.8).","f(t) = a·bᵗ: a is the starting amount (the y-intercept).","Half-life: multiply by ½ each period: A·(½)^(t/h)."],
 [()=>{const a=ri(1,6),b=pick([2,3]),t=ri(3,6);return mk("num",`f(t) = ${a}·${b}^t. Find f(${t}).`,a*Math.pow(b,t),"Substitute t and evaluate the power first.",`${a} × ${b}^${t} = ${a*Math.pow(b,t)}`,{js:`${a}*${b}**${t}`})},
  ()=>{const P_=ri(2,20)*100,r=ri(3,9),t=ri(2,6);const v=P_*Math.pow(1+r/100,t);if(Math.abs((v*100)%1-0.5)<0.03)return TOPIC_BY_ID["exp-growth"].gens[1]();return mk("num",`$${P_} is invested at ${r}% interest compounded yearly. How much is it worth after ${t} years? (Round to the nearest cent.)`,rdn(v,2),"A = P(1 + r)ᵗ.",`${P_} × ${1+r/100}^${t} = ${rdn(v,2)}`,{js:`${P_}*(1+${r}/100)**${t}`,jtol:0.0050001})},
  ()=>{const r=ri(2,9)*pick([1,2,5]),up=Math.random()<0.5;return mk("num",`A quantity ${up?"grows":"decays"} ${r}% each year. What is the yearly ${up?"growth":"decay"} factor b?`,rdn(1+(up?1:-1)*r/100,4),up?"Growth factor b = 1 + r.":"Decay factor b = 1 − r.",`b = 1 ${up?"+":"−"} ${r/100} = ${rdn(1+(up?1:-1)*r/100,4)}`,{js:`1${up?"+":"-"}${r}/100`})},
  ()=>{const k=ri(2,5),h=ri(2,8),A=Math.pow(2,k)*ri(2,9);return mk("num",`A sample has ${A} grams and a half-life of ${h} years. How many grams remain after ${k*h} years?`,A/Math.pow(2,k),"There are k half-lives; halve the amount k times.",`${k*h}/${h} = ${k} half-lives; ${A} × (1/2)^${k} = ${A/Math.pow(2,k)}`,{js:`${A}*0.5**(${k*h}/${h})`})},
  ()=>{const d=ri(2,6),k=ri(2,5),P_=ri(2,9)*10;return mk("num",`A bacteria population doubles every ${d} hours. If it starts at ${P_}, what is it after ${d*k} hours?`,P_*Math.pow(2,k),"Number of doublings = hours ÷ d; multiply by 2 that many times.",`${d*k}/${d} = ${k} doublings; ${P_} × 2^${k} = ${P_*Math.pow(2,k)}`,{js:`${P_}*2**(${d*k}/${d})`})}]);
T("exp-vs-lin","a1seq","F.LE.1","Linear vs. exponential models",["exp-growth","lin-model"],
 "Linear functions add a constant amount each step; exponential functions multiply by a constant factor. Eventually an exponential with b > 1 beats any linear function.",
 ["Constant differences → linear. Constant ratios → exponential.","Table with x = 0, 1, 2: y = a·bˣ where a = y(0) and b = y(1) ÷ y(0).","Compare models by evaluating them at the same x-values."],
 [()=>{const lin_=Math.random()<0.5;const a=ri(2,6);const ys=[0,1,2,3].map(i=>lin_?a+3*i:a*Math.pow(3,i));return mcq(`A table has x = 0, 1, 2, 3 and y = ${ys.join(", ")}. Is the relationship linear or exponential?`,lin_?"Linear":"Exponential",[lin_?"Exponential":"Linear"],"Constant differences → linear; constant ratios → exponential.",lin_?"the differences are all 3":"the ratios are all 3",{js:`(${ys[1]}-${ys[0]}===${ys[2]}-${ys[1]})===${lin_}`})},
  ()=>{const a=ri(1,4),m=ri(5,12),c=ri(0,10);let n=0;while(a*Math.pow(2,n)<=m*n+c)n++;return mk("num",`Compare f(x) = ${a}·2^x and g(x) = ${m}x + ${c}. What is the smallest whole number x for which f(x) > g(x)?`,n,"Make a table of values and find the first x where the exponential is larger.",`f(${n}) = ${a*Math.pow(2,n)} > g(${n}) = ${m*n+c}, and it was not larger at x = ${n-1}`,{js:`(()=>{let n=0;while(!(${a}*2**n>${m}*n+${c}))n++;return n})()`})},
  ()=>{const a=ri(2,7),b=ri(2,4);return mk("eq",`A table gives y = ${a} at x = 0, y = ${a*b} at x = 1 and y = ${a*b*b} at x = 2. Write the exponential equation y = a·b^x.`,`y = ${a}(${b})^x`,"a = y at x = 0; b = the ratio between consecutive y-values.",`a = ${a}; b = ${a*b}/${a} = ${b}`,{pe:`y-${a}*${b}**x`})}]);
T("poly-mult","a1poly","A.APR.1","Multiplying polynomials",["poly-add","distrib"],
 "To multiply polynomials, multiply every term of one by every term of the other (distributive property / FOIL), then combine like terms.",
 ["Binomial × binomial (FOIL): (x + 3)(x − 5) = x² − 5x + 3x − 15 = x² − 2x − 15.","Special products: (a + b)² = a² + 2ab + b² and (a + b)(a − b) = a² − b².","Write the answer from highest to lowest power."],
 [()=>{const a=rnz(-5,5),b=rnz(-4,4),c=rnz(-4,4),d=ri(-6,6);return mk("poly",`Expand: ${a}x(${quad(b,c,d)})`,polyStr([[a*b,"x^3"],[a*c,"x^2"],[a*d,"x"]]),"Distribute the monomial to every term.",`${a}x·${P(b)}x² = ${a*b}x³; ${a}x·${P(c)}x = ${a*c}x²; ${a}x·${P(d)} = ${a*d}x`,{pe:`${a}*x*(${b}*x*x+${c}*x+${d})`})},
  ()=>{const p=rnz(-9,9),q=rnz(-9,9);return mk("poly",`Expand: (x ${p<0?"-":"+"} ${Math.abs(p)})(x ${q<0?"-":"+"} ${Math.abs(q)})`,quad(1,p+q,p*q),"FOIL: first, outer, inner, last; combine the middle terms.",`x² + (${p}+${P(q)})x + ${p}·${P(q)} = ${quad(1,p+q,p*q)}`,{pe:`(x+(${p}))*(x+(${q}))`})},
  ()=>{const a=ri(2,5),b=rnz(-6,6),c=ri(1,5),d=rnz(-6,6);return mk("poly",`Expand: (${lin(a,b)})(${lin(c,d)})`,quad(a*c,a*d+b*c,b*d),"FOIL, then combine like terms.",`${a*c}x² + (${a*d}+${P(b*c)})x + ${b*d}`,{pe:`(${a}*x+(${b}))*(${c}*x+(${d}))`})},
  ()=>{const a=ri(1,4),b=rnz(-8,8);return mk("poly",`Expand: (${lin(a,b)})^2`,quad(a*a,2*a*b,b*b),"(A + B)² = A² + 2AB + B².",`(${a}x)² + 2(${a}x)(${b}) + ${b}² = ${quad(a*a,2*a*b,b*b)}`,{pe:`(${a}*x+(${b}))**2`})},
  ()=>{const a=ri(1,5),b=ri(1,9);return mk("poly",`Expand: (${cf(a,"x")} + ${b})(${cf(a,"x")} - ${b})`,quad(a*a,0,-b*b),"Difference of squares: (A + B)(A − B) = A² − B².",`(${a}x)² − ${b}² = ${quad(a*a,0,-b*b)}`,{pe:`(${a}*x+${b})*(${a}*x-${b})`})},
  ()=>{const a=rnz(-5,5),b=rnz(-4,4),c=rnz(-6,6);return mk("poly",`Expand: (x ${a<0?"-":"+"} ${Math.abs(a)})(${quad(1,b,c)})`,polyStr([[1,"x^3"],[a+b,"x^2"],[a*b+c,"x"],[a*c,""]]),"Multiply each term of the trinomial by x and by the constant, then combine.",`x³ + (${b}+${P(a)})x² + (${c}+${P(a*b)})x + ${P(a*c)}`,{pe:`(x+(${a}))*(x*x+${b}*x+${c})`})}]);
T("fn-transform","a1fn","F.BF.3","Transformations of functions",["func-eval","poly-mult"],
 "Adding to the output moves a graph up/down; adding inside the input moves it left/right; multiplying stretches or flips it.",
 ["f(x) + k shifts up k; f(x − h) shifts right h (the sign inside is opposite to the direction).","k·f(x) stretches vertically by |k|; −f(x) reflects over the x-axis.","For y = |x − h| + k or y = (x − h)² + k the vertex is (h, k)."],
 [()=>{const h=rnz(-5,5),k=rnz(-6,6);return mk("poly",`The graph of f(x) = x² is shifted ${Math.abs(h)} units ${h>0?"right":"left"} and ${Math.abs(k)} units ${k>0?"up":"down"}. Write the new function g(x) in expanded form.`,quad(1,-2*h,h*h+k),"g(x) = (x − h)² + k with h the rightward shift; expand.",`(x − ${P(h)})² + ${P(k)} = ${quad(1,-2*h,h*h+k)}`,{pe:`(x-(${h}))**2+(${k})`})},
  ()=>{const a=rnz(-4,4),b=ri(-6,6),k=rnz(-6,6);return mk("poly",`If f(x) = ${lin(a,b)}, write g(x) = f(x) + (${k}) as a simplified expression.`,lin(a,b+k),"Adding k to the output adds k to the constant term.",`${lin(a,b)} + ${P(k)} = ${lin(a,b+k)}`,{pe:`${a}*x+${b}+${k}`})},
  ()=>{const a=rnz(-4,4),b=ri(-6,6),h=rnz(-5,5);return mk("poly",`If f(x) = ${lin(a,b)}, write g(x) = f(x ${h<0?"+":"-"} ${Math.abs(h)}) as a simplified expression.`,lin(a,b-a*h),"Replace x by (x − h) and simplify.",`${a}(x − ${P(h)}) + ${b} = ${lin(a,b-a*h)}`,{pe:`${a}*(x-(${h}))+${b}`})},
  ()=>{const a=pick([2,3,-1,-2,4]),h=rnz(-5,5),k=ri(-6,6);return mk("pair",`The graph of y = ${a===1?"":a===-1?"-":a}(x ${h<0?"+":"-"} ${Math.abs(h)})^2 ${k<0?"-":"+"} ${Math.abs(k)} is a parabola. What is its vertex?`,`(${h}, ${k})`,"For y = a(x − h)² + k the vertex is (h, k); read the sign of h carefully.",`h = ${h}, k = ${k}`,{eqs:[`x=${h}`,`y=${k}`]})}]);
T("factor-gcf","a1poly","A.SSE.2","Factoring out the greatest common factor",["poly-mult","distrib"],
 "Factoring undoes multiplying. First pull out the greatest common factor (GCF) of all the terms, including any common power of x.",
 ["GCF = largest number dividing all coefficients × lowest power of x in every term.","6x² + 9x = 3x(2x + 3). Check by expanding.","Grouping: x³ + 2x² + 3x + 6 = x²(x + 2) + 3(x + 2) = (x + 2)(x² + 3)."],
 [()=>{const g=ri(2,6);let p,q;do{p=ri(1,5);q=rnz(-7,7)}while(gcd(p,q)!==1);return mk("expr",`Factor completely: ${polyStr([[g*p,"x^2"],[g*q,"x"]])}`,`${g}x(${lin(p,q)})`,"Take out the GCF of the coefficients and the lowest power of x.",`GCF = ${g}x; ${g*p}x² ÷ ${g}x = ${cf(p,"x")}; ${g*q}x ÷ ${g}x = ${q}`,{form:"factor",fdeg:[1,1],pe:`${g*p}*x*x+${g*q}*x`})},
  ()=>{const g=ri(1,5);let a,b,c;do{a=ri(1,3);b=ri(1,4);c=ri(1,4)}while(b*b-4*a*c>=0||gcd(gcd(a,b),c)!==1);return mk("expr",`Factor out the GCF: ${polyStr([[g*a,"x^3"],[g*b,"x^2"],[g*c,"x"]])}`,`${g===1?"":g}x(${quad(a,b,c)})`,"Factor out the GCF of coefficients and the lowest power of x; the quadratic left over can't be factored further.",`GCF = ${g===1?"":g}x`,{form:"factor",fdeg:[1,2],pe:`${g*a}*x**3+${g*b}*x**2+${g*c}*x`})},
  ()=>{const g=ri(2,6);let p,q;do{p=ri(1,5);q=ri(1,7)}while(gcd(p,q)!==1);return mk("expr",`Factor out a negative GCF: ${polyStr([[-g*p,"x^2"],[-g*q,"x"]])}`,`-${g}x(${lin(p,q)})`,"Factor out −GCF so the leading term inside is positive.",`GCF = −${g}x; ${-g*p}x² ÷ (−${g}x) = ${cf(p,"x")}; ${-g*q}x ÷ (−${g}x) = ${q}`,{form:"factor",fdeg:[1,1],pe:`-${g*p}*x*x-${g*q}*x`})},
  ()=>{const a=ri(1,6),b=ri(1,6);return mk("expr",`Factor by grouping: x^3 + ${a}x^2 + ${b}x + ${a*b}`,`(x + ${a})(x^2 + ${b})`,"Group in pairs, factor each pair, then factor out the common binomial.",`x²(x + ${a}) + ${b}(x + ${a}) = (x + ${a})(x² + ${b})`,{form:"factor",fdeg:[1,2],pe:`x**3+${a}*x**2+${b}*x+${a*b}`})}]);
const F11=(p,q)=>`${fx(-p)}${fx(-q)}`;   // (x + p)(x + q)
T("factor-trinomial","a1poly","A.SSE.3a","Factoring x² + bx + c",["factor-gcf"],
 "To factor x² + bx + c, find two numbers p and q with p·q = c and p + q = b. Then x² + bx + c = (x + p)(x + q).",
 ["List factor pairs of c; choose the pair that adds to b.","If c > 0, p and q have the same sign (the sign of b). If c < 0, they have opposite signs.","Check by multiplying (FOIL)."],
 [()=>{const p=ri(1,9),q=ri(1,9);return mk("expr",`Factor: ${quad(1,p+q,p*q)}`,F11(p,q),"Find p, q with p·q = c and p + q = b.",`${p}·${q} = ${p*q} and ${p}+${q} = ${p+q}`,{form:"factor",fdeg:[1,1],pe:`x*x+${p+q}*x+${p*q}`})},
  ()=>{const p=ri(1,9),q=ri(1,9);return mk("expr",`Factor: ${quad(1,-(p+q),p*q)}`,F11(-p,-q),"c > 0 and b < 0, so both numbers are negative.",`(−${p})(−${q}) = ${p*q}; (−${p})+(−${q}) = ${-(p+q)}`,{form:"factor",fdeg:[1,1],pe:`x*x-${p+q}*x+${p*q}`})},
  ()=>{const p=ri(1,9);let q;do{q=ri(1,9)}while(q===p);const s=Math.random()<0.5?1:-1;const a=s*p,b=-s*q;return mk("expr",`Factor: ${quad(1,a+b,a*b)}`,F11(a,b),"c < 0, so one number is positive and one negative; their sum is b.",`${a}·${P(b)} = ${a*b}; ${a}+${P(b)} = ${a+b}`,{form:"factor",fdeg:[1,1],pe:`x*x+${a+b}*x+${a*b}`})},
  ()=>{const p=ri(2,12),q=ri(2,12);const s=pick([[1,1],[-1,-1],[1,-1],[-1,1]]);const a=s[0]*p,b=s[1]*q;return mk("expr",`Factor: ${quad(1,a+b,a*b)}`,F11(a,b),"Find two numbers with product c and sum b.",`${a}·${P(b)} = ${a*b}; ${a}+${P(b)} = ${a+b}`,{form:"factor",fdeg:[1,1],pe:`x*x+${a+b}*x+${a*b}`})}]);
T("factor-a","a1poly","A.SSE.3a","Factoring ax² + bx + c",["factor-trinomial"],
 "When the leading coefficient is not 1, find two numbers whose product is a·c and sum is b, split the middle term, and factor by grouping — or test factor pairs.",
 ["Multiply a·c, find two numbers m, n with m·n = ac and m + n = b.","Split bx into mx + nx and factor by grouping.","Check with FOIL; always take out a GCF first."],
 [()=>{let m,n,p,q;do{m=ri(2,5);n=ri(1,3);p=ri(1,7);q=ri(1,7)}while(gcd(m,p)!==1||gcd(n,q)!==1||gcd(gcd(m*n,m*q+n*p),p*q)!==1);return mk("expr",`Factor: ${quad(m*n,m*q+n*p,p*q)}`,`${bf(m,p)}${bf(n,q)}`,"Find two numbers with product ac and sum b, split the middle term, group.",`ac = ${m*n*p*q}; split ${m*q+n*p}x into ${m*q}x + ${n*p}x; factor by grouping`,{form:"factor",fdeg:[1,1],pe:`${m*n}*x*x+${m*q+n*p}*x+${p*q}`})},
  ()=>{let m,n,p,q;do{m=ri(2,5);n=ri(1,3);p=-ri(1,7);q=-ri(1,7)}while(gcd(m,p)!==1||gcd(n,q)!==1||gcd(gcd(m*n,m*q+n*p),p*q)!==1);return mk("expr",`Factor: ${quad(m*n,m*q+n*p,p*q)}`,`${bf(m,p)}${bf(n,q)}`,"Both constants are negative since c > 0 and b < 0.",`ac = ${m*n*p*q}; split ${m*q+n*p}x into ${m*q}x + ${n*p}x; group`,{form:"factor",fdeg:[1,1],pe:`${m*n}*x*x+${m*q+n*p}*x+${p*q}`})},
  ()=>{let m,n,p,q;do{m=ri(2,6);n=ri(1,3);p=rnz(-7,7);q=rnz(-7,7)}while(gcd(m,p)!==1||gcd(n,q)!==1||gcd(gcd(m*n,m*q+n*p),p*q)!==1||m*q+n*p===0);return mk("expr",`Factor: ${quad(m*n,m*q+n*p,p*q)}`,`${bf(m,p)}${bf(n,q)}`,"Try factor pairs of a and c so the outer + inner terms give b.",`${m}x·${P(q)}+${P(p)}·${n}x = ${m*q+n*p}x`,{form:"factor",fdeg:[1,1],pe:`${m*n}*x*x+${m*q+n*p}*x+${p*q}`})}]);
T("factor-dos","a1poly","A.SSE.2","Difference of squares & perfect-square trinomials",["factor-trinomial"],
 "Two special patterns factor quickly: a² − b² = (a − b)(a + b), and a² ± 2ab + b² = (a ± b)².",
 ["Difference of squares: A² − B² = (A − B)(A + B). A sum of squares does not factor.","Perfect square trinomial: first and last terms are squares and the middle is twice their product.","Always check for a GCF first."],
 [()=>{const k=ri(2,12);return mk("expr",`Factor: x^2 - ${k*k}`,`(x - ${k})(x + ${k})`,"A² − B² = (A − B)(A + B).",`x² − ${k}² = (x − ${k})(x + ${k})`,{form:"factor",fdeg:[1,1],pe:`x*x-${k*k}`})},
  ()=>{let a,b;do{a=ri(2,6);b=ri(1,9)}while(gcd(a,b)!==1);return mk("expr",`Factor: ${a*a}x^2 - ${b*b}`,`(${a}x - ${b})(${a}x + ${b})`,"A = ax, B = b: A² − B² = (A − B)(A + B).",`(${a}x)² − ${b}² = (${a}x − ${b})(${a}x + ${b})`,{form:"factor",fdeg:[1,1],pe:`${a*a}*x*x-${b*b}`})},
  ()=>{const k=ri(1,9),s=Math.random()<0.5?1:-1;return mk("expr",`Factor: ${quad(1,2*k*s,k*k)}`,`(x ${s<0?"-":"+"} ${k})^2`,"Perfect square trinomial: x² ± 2kx + k² = (x ± k)².",`${k}² = ${k*k} and 2·${k} = ${2*k}`,{form:"factor",fdeg:[1,1],pe:`x*x+${2*k*s}*x+${k*k}`})},
  ()=>{let a,b;do{a=ri(2,5);b=ri(1,7)}while(gcd(a,b)!==1);const s=Math.random()<0.5?1:-1;return mk("expr",`Factor: ${quad(a*a,2*a*b*s,b*b)}`,`(${a}x ${s<0?"-":"+"} ${b})^2`,"Check: first term (ax)², last term b², middle 2·ax·b.",`(${a}x)² ${s<0?"−":"+"} 2(${a}x)(${b}) + ${b}²`,{form:"factor",fdeg:[1,1],pe:`${a*a}*x*x+${2*a*b*s}*x+${b*b}`})}]);
T("factor-full","a1poly","A.SSE.2","Factoring completely",["factor-a","factor-dos"],
 "Factor completely: pull out the GCF first, then keep factoring what is left (trinomials, differences of squares) until no factor can be broken down further.",
 ["Step 1: GCF. Step 2: look for difference of squares or a trinomial pattern. Step 3: check each factor again.","x⁴ − 16 = (x² + 4)(x² − 4) = (x² + 4)(x − 2)(x + 2).","The sum of squares x² + k² doesn't factor over the integers."],
 [()=>{const g=ri(2,5),k=ri(1,6);return mk("expr",`Factor completely: ${polyStr([[g,"x^2"],[-g*k*k,""]])}`,`${g}(x - ${k})(x + ${k})`,"GCF first, then difference of squares.",`${g}(x² − ${k*k}) = ${g}(x − ${k})(x + ${k})`,{form:"factor",fdeg:[1,1],pe:`${g}*x*x-${g*k*k}`})},
  ()=>{const g=ri(2,5),p=ri(1,6),q=ri(1,6);return mk("expr",`Factor completely: ${polyStr([[g,"x^2"],[g*(p+q),"x"],[g*p*q,""]])}`,`${g}(x + ${p})(x + ${q})`,"GCF first, then factor the trinomial.",`${g}(x² + ${p+q}x + ${p*q}) = ${g}(x + ${p})(x + ${q})`,{form:"factor",fdeg:[1,1],pe:`${g}*(x*x+${p+q}*x+${p*q})`})},
  ()=>{const k=ri(1,7);return mk("expr",`Factor completely: x^3 - ${k*k}x`,`x(x - ${k})(x + ${k})`,"GCF x first, then difference of squares.",`x(x² − ${k*k}) = x(x − ${k})(x + ${k})`,{form:"factor",fdeg:[1,1,1],pe:`x**3-${k*k}*x`})},
  ()=>{const k=ri(1,4);return mk("expr",`Factor completely: x^4 - ${Math.pow(k,4)}`,`(x^2 + ${k*k})(x - ${k})(x + ${k})`,"Difference of squares twice: x⁴ − k⁴ = (x² + k²)(x² − k²).",`(x² + ${k*k})(x² − ${k*k}) = (x² + ${k*k})(x − ${k})(x + ${k})`,{form:"factor",fdeg:[1,1,2],pe:`x**4-${Math.pow(k,4)}`})}]);
T("quad-factor","a1quad","A.REI.4b","Solving quadratics by factoring",["factor-trinomial","factor-a"],
 "Zero-product property: if A·B = 0 then A = 0 or B = 0. Move everything to one side, factor, and set each factor equal to 0.",
 ["Write the equation as ax² + bx + c = 0 first.","Factor, then solve each factor = 0.","Quadratics can have two solutions, one (a double root) or none."],
 [()=>{const p=rnz(-9,9),q=rnz(-9,9);return mk("set",`Solve: (x ${p<0?"+":"-"} ${Math.abs(p)})(x ${q<0?"+":"-"} ${Math.abs(q)}) = 0`,`${p}, ${q}`,"Zero-product property: set each factor to 0.",`x = ${p} or x = ${q}`,{fx:`(x-(${p}))*(x-(${q}))`,nroots:p===q?1:2,complete:false})},
  ()=>{const p=rnz(-9,9),q=rnz(-9,9);return mk("set",`Solve: ${quad(1,-(p+q),p*q)} = 0`,`${p}, ${q}`,"Factor into (x − p)(x − q) = 0.",`${quad(1,-(p+q),p*q)} = (x − ${P(p)})(x − ${P(q)})`,{fx:`x*x-(${p+q})*x+(${p*q})`,nroots:p===q?1:2,complete:false})},
  ()=>{const k=rnz(-9,9);const s=Math.random()<0.5;return mk("set",s?`Solve: x^2 = ${k}x`:`Solve: ${polyStr([[1,"x^2"],[-k,"x"]])} = 0`,`0, ${k}`,"Factor out x, then set each factor to 0 (never divide by x).",`x(x − ${P(k)}) = 0 → x = 0 or x = ${k}`,{fx:`x*x-(${k})*x`,nroots:2})},
  ()=>{let m,n,p,q;do{m=ri(2,4);n=ri(1,3);p=rnz(-6,6);q=rnz(-6,6)}while(gcd(m,p)!==1||gcd(n,q)!==1);return mk("set",`Solve: ${quad(m*n,m*q+n*p,p*q)} = 0`,`${frs(-p,m)}, ${frs(-q,n)}`,"Factor with the ac method, then solve each factor.",`(${lin(m,p)})(${lin(n,q)}) = 0 → x = ${frs(-p,m)} or x = ${frs(-q,n)}`,{fx:`${m*n}*x*x+(${m*q+n*p})*x+(${p*q})`,nroots:new Set([frs(-p,m),frs(-q,n)]).size,complete:false})}]);
T("quad-sqrt","a1quad","A.REI.4b","Solving by square roots",["sqrt-basic","multistep-eq"],
 "If a quadratic is just x² (or a perfect square expression) equal to a number, isolate the square and take both square roots.",
 ["x² = k → x = ±√k (two solutions if k > 0; none if k < 0).","(x − h)² = k → x = h ± √k.","Give exact answers like 3 + √5 (type 3+sqrt(5))."],
 [()=>{const k=ri(2,12);return mk("set",`Solve: x^2 = ${k*k}`,`${-k}, ${k}`,"Take ± the square root.",`x = ±√${k*k} = ±${k}`,{fx:`x*x-${k*k}`,nroots:2})},
  ()=>{const a=ri(2,6),k=ri(2,9);return mk("set",`Solve: ${a}x^2 = ${a*k*k}`,`${-k}, ${k}`,"Divide by a first, then take both roots.",`x² = ${k*k} → x = ±${k}`,{fx:`${a}*x*x-${a*k*k}`,nroots:2})},
  ()=>{const h=rnz(-8,8),k=ri(1,9);return mk("set",`Solve: (x ${h<0?"+":"-"} ${Math.abs(h)})^2 = ${k*k}`,`${h-k}, ${h+k}`,"Take ± the square root of both sides, then solve for x.",`x ${h<0?"+":"−"} ${Math.abs(h)} = ±${k} → x = ${h-k} or ${h+k}`,{fx:`(x-(${h}))**2-${k*k}`,nroots:2})},
  ()=>{let n;do{n=ri(2,30)}while(SQ(n));return mk("set",`Solve (give exact answers): x^2 = ${n}`,`${rs(1,n)}, ${rs(-1,n)}`,"x = ±√n; simplify the radical if possible.",`x = ±√${n} = ±${M(rs(1,n))}`,{fx:`x*x-${n}`,nroots:2})},
  ()=>{const k=ri(1,9);return mk("set",`Solve: x^2 + ${k} = 0`,"none","A square is never negative, so x² = −k has no real solution.",`x² = −${k} has no real solution`,{fx:`x*x+${k}`})}]);
T("rad-simp","a1rad","N.RN.2","Simplifying radicals",["sqrt-basic","irrational"],
 "To simplify √n, pull out the largest perfect-square factor: √50 = √(25·2) = 5√2. A radical is simplified when its radicand has no perfect-square factor.",
 ["Factor the radicand: √72 = √(36·2) = 6√2.","√(ab) = √a · √b and c√n means c times √n.","Type radicals like 5sqrt(2); the answer must be fully simplified."],
 [()=>{let n;do{n=ri(8,150)}while(rparts(n)[0]===1);return mk("expr",`Simplify: sqrt(${n})`,rs(1,n),"Pull out the largest perfect-square factor.",`${n} = ${rparts(n)[0]**2} × ${rparts(n)[1]}, so √${n} = ${M(rs(1,n))}`,{form:"rad",pe:`Math.sqrt(${n})`})},
  ()=>{const c=ri(2,6);let n;do{n=ri(8,60)}while(rparts(n)[0]===1);return mk("expr",`Simplify: ${c}sqrt(${n})`,rs(c,n),"Simplify the radical, then multiply by the coefficient.",`${c}√${n} = ${c}·${rparts(n)[0]}√${rparts(n)[1]}`,{form:"rad",pe:`${c}*Math.sqrt(${n})`})},
  ()=>{const a=ri(2,9),m=pick([2,3,5,6,7]);return mk("expr",`Simplify: sqrt(${a*a*m})`,rs(1,a*a*m),"√(a²·m) = a√m.",`${a*a*m} = ${a*a}·${m}`,{form:"rad",pe:`Math.sqrt(${a*a*m})`})},
  ()=>{let n,d;do{n=ri(8,100);d=ri(2,12)}while(rparts(n)[0]===1||rparts(n)[1]===1);const [k,m]=rparts(n);const g=gcd(k,d);const num=k/g,den=d/g;return mk("expr",`Simplify: sqrt(${n})/${d}`,(num===1?"":num)+"sqrt("+m+")"+(den===1?"":"/"+den),"Simplify the radical, then reduce the coefficient against the denominator.",`√${n} = ${k}√${m}; ${k}√${m}/${d} reduced by ${g}`,{form:"rad",pe:`Math.sqrt(${n})/${d}`})}]);
T("rad-ops","a1rad","N.RN.3","Operations with radicals",["rad-simp","poly-mult"],
 "Like radicals add like like terms: 3√2 + 5√2 = 8√2. Radicals multiply by multiplying the insides, and you rationalize a denominator by multiplying top and bottom by the radical.",
 ["Add/subtract only like radicals (same radicand): simplify first, then combine.","√a·√b = √(ab); (a + √n)(a − √n) = a² − n.","Rationalize: a/√n = a√n/n."],
 [()=>{const a=ri(2,9),b=ri(2,9),n=pick([2,3,5,6,7]);return mk("expr",`Simplify: ${a}sqrt(${n}) + ${b}sqrt(${n})`,`${a+b}sqrt(${n})`,"Combine like radicals like like terms.",`(${a} + ${b})√${n}`,{form:"rad",pe:`${a+b}*Math.sqrt(${n})`})},
  ()=>{const a=ri(2,12),b=ri(2,12);return mk("expr",`Simplify: sqrt(${a})·sqrt(${b})`,rs(1,a*b),"√a · √b = √(ab), then simplify.",`√${a*b} = ${M(rs(1,a*b))}`,{form:"rad",pe:`Math.sqrt(${a*b})`})},
  ()=>{const a=ri(1,9),n=pick([2,3,5,6,7,10,11]);return mk("num",`Simplify: (${a} + sqrt(${n}))(${a} - sqrt(${n}))`,a*a-n,"Difference of squares: the radicals cancel.",`${a}² − (√${n})² = ${a*a} − ${n} = ${a*a-n}`,{js:`(${a}+Math.sqrt(${n}))*(${a}-Math.sqrt(${n}))`,jtol:1e-9})},
  ()=>{const n=pick([2,3,5,6,7,10,11]);const a=ri(2,12);const g=gcd(a,n);return mk("expr",`Rationalize the denominator: ${a}/sqrt(${n})`,`${a/g===1?"":a/g}sqrt(${n})${n/g===1?"":"/"+n/g}`,"Multiply the numerator and denominator by √n.",`${a}√${n}/${n} reduced by ${g}`,{form:"rad",pe:`${a}/Math.sqrt(${n})`})},
  ()=>{const a=ri(2,6),b=ri(2,6),m=pick([2,3,5,6]);return mk("expr",`Simplify: sqrt(${a*a*m}) + sqrt(${b*b*m})`,`${a+b}sqrt(${m})`,"Simplify each radical first; then they are like radicals.",`${a}√${m} + ${b}√${m} = ${a+b}√${m}`,{form:"rad",pe:`${a+b}*Math.sqrt(${m})`})}]);
T("rat-irr","a1rad","N.RN.3","Rational & irrational numbers: sums and products",["rad-simp"],
 "A rational plus a rational is rational; a nonzero rational times an irrational is irrational; a rational plus an irrational is irrational. Two irrationals can give either.",
 ["Rational + rational, rational × rational → rational.","Rational + irrational → irrational. Nonzero rational × irrational → irrational.","Irrational + irrational (or ×) can be rational: √2·√2 = 2."],
 [()=>{const a=ri(1,9),n=pick([2,3,5,6,7,10]);return mcq(`Is ${a} + √${n} rational or irrational?`,"Irrational",["Rational"],"Rational + irrational is always irrational.","√"+n+" is irrational, adding a rational can't make it rational.")},
  ()=>{const a=ri(2,9),n=pick([2,3,5,6,7,10]);return mcq(`Is ${a}·√${n} rational or irrational?`,"Irrational",["Rational"],"A nonzero rational times an irrational is irrational.",`√${n} is irrational and ${a} ≠ 0.`)},
  ()=>{const n=pick([2,3,5,6,7,10]);const t=pick([["√"+n+" · √"+n,"Rational"],["√"+n+" + √"+n,"Irrational"],["√"+n+" − √"+n,"Rational"],["√"+n+" · √"+(n+1),"Irrational"]]);const nn=SQ(n+1)&&t[0].includes(String(n+1))?null:1;if(!nn)return TOPIC_BY_ID["rat-irr"].gens[2]();return mcq(`Is ${t[0]} rational or irrational?`,t[1],[t[1]==="Rational"?"Irrational":"Rational"],"Compute the result: some irrational combinations are rational.",t[1]==="Rational"?"The result simplifies to a rational number (like 0 or a perfect square).":"The result is a nonzero multiple of an irrational number or a root of a non-square.")}]);
T("quad-cs","a1quad","A.REI.4b","Completing the square",["quad-sqrt","factor-dos"],
 "Completing the square turns x² + bx into a perfect square trinomial by adding (b/2)². It solves any quadratic and reveals the vertex.",
 ["x² + bx + (b/2)² = (x + b/2)².","x² + bx + c = (x + p)² + q with p = b/2 and q = c − p².","Solve x² + bx = d: add (b/2)² to both sides, take square roots."],
 [()=>{const b=2*ri(1,9)*pick([1,-1]);return mk("num",`What number must be added to x^2 ${b<0?"-":"+"} ${Math.abs(b)}x to complete the square?`,(b/2)**2,"Add (b/2)².",`(${b}/2)² = ${(b/2)**2}`,{js:`(${b}/2)**2`})},
  ()=>{const p=rnz(-8,8),q=ri(-12,12);return mk("num",`Write x² ${2*p<0?"-":"+"} ${Math.abs(2*p)}x ${p*p+q<0?"-":"+"} ${Math.abs(p*p+q)} in the form (x + p)² + q. Find p.`,p,"p = b/2.",`p = ${2*p}/2 = ${p}`,{js:`${2*p}/2`})},
  ()=>{const p=rnz(-8,8),q=ri(-12,12);return mk("num",`Write x² ${2*p<0?"-":"+"} ${Math.abs(2*p)}x ${p*p+q<0?"-":"+"} ${Math.abs(p*p+q)} in the form (x + p)² + q. Find q.`,q,"q = c − p².",`q = ${p*p+q} − ${p*p} = ${q}`,{js:`${p*p+q}-(${2*p}/2)**2`})},
  ()=>{const p=rnz(-6,6);const d=ri(1,20);const k=d+p*p;return mk("set",`Solve by completing the square (exact form): x² ${2*p<0?"-":"+"} ${Math.abs(2*p)}x = ${d}`,`${-p}+sqrt(${k}), ${-p}-sqrt(${k})`,"Add p² to both sides, write the left as (x + p)², then take square roots.",`(x ${p<0?"−":"+"} ${Math.abs(p)})² = ${k} → x = ${-p} ± √${k}`,{fx:`x*x+${2*p}*x-${d}`,nroots:2})}]);
T("quad-formula","a1quad","A.REI.4a","The quadratic formula & discriminant",["quad-cs"],
 "For ax² + bx + c = 0, x = (−b ± √(b² − 4ac)) / (2a). The discriminant D = b² − 4ac tells how many real solutions there are.",
 ["D > 0: two real solutions. D = 0: one. D < 0: none (real).","Write the equation in standard form first so a, b, c are right.","Round only at the end; type solutions separated by a comma, e.g. 1.5, -2."],
 [()=>{const a=rnz(-4,5),b=rnz(-9,9),c=rnz(-9,9);return mk("num",`Find the discriminant of ${quad(a,b,c)} = 0.`,b*b-4*a*c,"D = b² − 4ac.",`(${b})² − 4(${a})(${c}) = ${b*b-4*a*c}`,{js:`${b}*${b}-4*(${a})*(${c})`})},
  ()=>{const a=rnz(-3,4),b=rnz(-8,8),c=rnz(-8,8);const D=b*b-4*a*c;return mk("num",`How many real solutions does ${quad(a,b,c)} = 0 have?`,D>0?2:D===0?1:0,"Compute D = b² − 4ac: positive → 2, zero → 1, negative → 0.",`D = ${D}`,{js:`(${b}*${b}-4*(${a})*(${c}))>0?2:(${b}*${b}-4*(${a})*(${c}))===0?1:0`})},
  ()=>{let a,x1,x2;do{a=ri(1,4);x1=ri(-5,5);x2=ri(-5,5)}while(x1===x2);const b=-a*(x1+x2),c=a*x1*x2;const D=b*b-4*a*c;return mk("set",`Solve using the quadratic formula: ${quad(a,b,c)} = 0`,`${x1}, ${x2}`,"x = (−b ± √D) / 2a.",`D = ${D}, √D = ${Math.sqrt(D)}; x = (${-b} ± ${Math.sqrt(D)})/${2*a} = ${x1}, ${x2}`,{fx:`${a}*x*x+(${b})*x+(${c})`,nroots:2})},
  ()=>{let a,b,c,D,r1,r2;let g=0;do{a=rnz(-4,5);b=rnz(-9,9);c=rnz(-9,9);D=b*b-4*a*c;r1=(-b+Math.sqrt(D))/(2*a);r2=(-b-Math.sqrt(D))/(2*a);g++}while(g<500&&(D<=0||SQ(D)||Math.abs(r1)>30||Math.abs(r2)>30||[r1,r2].some(r=>Math.abs(Math.abs(r*100)%1-0.5)<0.03)));
     if(D<=0||SQ(D))return TOPIC_BY_ID["quad-formula"].gens[2]();const A1=rdn(r1,2),A2=rdn(r2,2);return mk("set",`Solve ${quad(a,b,c)} = 0. Round each solution to the nearest hundredth.`,`${A1}, ${A2}`,"Use the quadratic formula, then round at the end.",`D = ${D}; x = (${-b} ± √${D})/${2*a} ≈ ${A1}, ${A2}`,{fx:`${a}*x*x+(${b})*x+(${c})`,round:2,nroots:2,ftol:0.006*(2*Math.abs(a)*Math.max(Math.abs(r1),Math.abs(r2))+Math.abs(b))+1e-6})},
  ()=>{let a,x1,x2;do{a=ri(2,4);x1=ri(-4,4);x2=ri(-4,4)}while(x1===x2);const b=-a*(x1+x2),c=a*x1*x2;return mk("set",`Solve: ${polyStr([[a,"x^2"]])} = ${polyStr([[-b,"x"],[-c,""]])}`,`${x1}, ${x2}`,"Move every term to one side to get standard form, then use the formula (or factor).",`${quad(a,b,c)} = 0 → x = ${x1} or ${x2}`,{fx:`${a}*x*x+(${b})*x+(${c})`,nroots:2})}]);
T("quad-graph","a1quad","F.IF.7a","Parabolas: vertex, axis & intercepts",["quad-factor","fn-transform"],
 "The graph of y = ax² + bx + c is a parabola. Its axis of symmetry is x = −b/(2a), and the vertex lies on the axis.",
 ["Axis of symmetry: x = −b/(2a). Vertex: plug that x back in to get y.","y-intercept: c.  x-intercepts: solve ax² + bx + c = 0 (for a(x − p)(x − q) they are p and q).","a > 0 opens up (vertex is a minimum); a < 0 opens down (a maximum)."],
 [()=>{const a=rnz(-4,4),h=ri(-6,6);const b=-2*a*h;return mk("num",`Find the axis of symmetry of y = ${quad(a,b,ri(-5,5))}. (Give the number k in x = k.)`,h,"x = −b/(2a).",`x = −(${b})/(2·${a}) = ${h}`,{js:`-(${b})/(2*${a})`})},
  ()=>{const a=rnz(-3,3),h=ri(-5,5),k=ri(-9,9);const b=-2*a*h,c=a*h*h+k;return mk("pair",`Find the vertex of y = ${quad(a,b,c)}.`,`(${h}, ${k})`,"x = −b/(2a); then substitute to find y.",`x = ${-b}/${2*a} = ${h}; y = ${a}(${h})² + ${b}(${h}) + ${c} = ${k}`,{eqs:[`2*${a}*x+(${b})=0`,`y=${a}*x*x+(${b})*x+(${c})`]})},
  ()=>{const a=rnz(-3,3),p=rnz(-6,6),q=rnz(-6,6);return mk("num",`Find the y-intercept of y = ${a===1?"":a===-1?"-":a}(x ${p<0?"+":"-"} ${Math.abs(p)})(x ${q<0?"+":"-"} ${Math.abs(q)}).`,a*p*q,"Set x = 0.",`${a}(−${P(p)})(−${P(q)}) = ${a*p*q}`,{js:`${a}*(0-(${p}))*(0-(${q}))`})},
  ()=>{const a=pick([-3,-2,-1,1,2,3]),h=ri(-5,5),k=ri(-9,9);return mk("num",`The parabola y = ${a===1?"":a===-1?"-":a}(x ${h<0?"+":"-"} ${Math.abs(h)})^2 ${k<0?"-":"+"} ${Math.abs(k)} has a ${a>0?"minimum":"maximum"} value. What is it?`,k,a>0?"a > 0 so the vertex is the lowest point: the minimum value is k.":"a < 0 so the vertex is the highest point: the maximum value is k.",`vertex (${h}, ${k}); ${a>0?"min":"max"} = ${k}`,{js:`${k}`})}]);
T("quad-apps","a1quad","A.CED.1","Quadratic word problems",["quad-formula"],
 "Many situations — projectiles, areas, products — lead to quadratic equations. Set up the equation from the story, solve, and keep only answers that make sense.",
 ["Projectile: h = −16t² + v₀t + h₀ (feet, seconds). It lands when h = 0.","Maximum/minimum occurs at the vertex t = −b/(2a).","Reject negative lengths and times."],
 [()=>{const v=16*ri(2,6);return mk("num",`A ball is thrown up from the ground: h = −16t² + ${v}t. After how many seconds does it land?`,v/16,"Set h = 0 and factor: −16t(t − v/16) = 0.",`−16t² + ${v}t = 0 → t(−16t + ${v}) = 0 → t = ${v/16}`,{js:`${v}/16`,u:" s"})},
  ()=>{const m=ri(1,4),h0=ri(2,12)*2;const v=32*m;return mk("num",`A rocket's height is h = −16t² + ${v}t + ${h0} (feet). What is its maximum height?`,16*m*m+h0,"Maximum at t = −b/(2a) = v/32; substitute back.",`t = ${v}/32 = ${m}; h = −16(${m})² + ${v}(${m}) + ${h0} = ${16*m*m+h0}`,{js:`-16*${m}**2+${v}*${m}+${h0}`,u:" ft"})},
  ()=>{const w=ri(3,12),k=ri(2,8);return mk("num",`A rectangle's length is ${k} more than its width, and its area is ${w*(w+k)}. Find the width.`,w,"Let width = x: x(x + k) = area; solve and keep the positive answer.",`x² + ${k}x − ${w*(w+k)} = 0 → (x − ${w})(x + ${w+k}) = 0 → x = ${w}`,{eqs:[`x*(x+${k})=${w*(w+k)}`]})},
  ()=>{const n=ri(3,15);return mk("num",`The product of two consecutive positive integers is ${n*(n+1)}. What is the smaller integer?`,n,"Let the integers be n and n + 1: n(n + 1) = product.",`n² + n − ${n*(n+1)} = 0 → (n − ${n})(n + ${n+1}) = 0 → n = ${n}`,{eqs:[`x*(x+1)=${n*(n+1)}`]})}]);
T("stat-box","a1stat","S.ID.1","Five-number summary & box plots",["stat-spread"],
 "The five-number summary — minimum, Q1, median, Q3, maximum — is what a box plot displays. The box holds the middle 50% of the data.",
 ["Sort the data first. Median = middle. Q1 and Q3 are the medians of the lower and upper halves (excluding the median when n is odd).","Range = max − min; IQR = Q3 − Q1.","About 25% of the data lies in each section of the box plot."],
 [()=>{const n=pick([9,11]);const a=shuffle(distinct(n,1,60));const s=a.slice().sort((x,y)=>x-y);const q1=n===9?(s[1]+s[2])/2:s[2],med=s[(n-1)/2],q3=n===9?(s[6]+s[7])/2:s[8];return mk("list",`Find the five-number summary (min, Q1, median, Q3, max) of: ${a.join(", ")}. Type the five numbers in order, separated by commas.`,`${s[0]}, ${q1}, ${med}, ${q3}, ${s[n-1]}`,"Sort the data; median in the middle; Q1 and Q3 are medians of the halves.",`sorted: ${s.join(", ")}`,{jsl:[`${s[0]}`,`${q1}`,`${med}`,`${q3}`,`${s[n-1]}`]})},
  ()=>{const mn=ri(1,20),q1=mn+ri(2,10),md=q1+ri(2,10),q3=md+ri(2,10),mx=q3+ri(2,12);return mk("num",`A box plot has minimum ${mn}, Q1 ${q1}, median ${md}, Q3 ${q3} and maximum ${mx}. What is the IQR?`,q3-q1,"IQR = Q3 − Q1.",`${q3} − ${q1} = ${q3-q1}`,{js:`${q3}-${q1}`})},
  ()=>{const mn=ri(1,20),q1=mn+ri(2,10),md=q1+ri(2,10),q3=md+ri(2,10),mx=q3+ri(2,12);return mk("num",`A box plot has minimum ${mn}, Q1 ${q1}, median ${md}, Q3 ${q3} and maximum ${mx}. What is the range?`,mx-mn,"Range = max − min.",`${mx} − ${mn} = ${mx-mn}`,{js:`${mx}-${mn}`})},
  ()=>{const n=ri(5,30)*4;return mk("num",`A data set has ${n} values. About how many values lie between Q1 and Q3?`,n/2,"The box (Q1 to Q3) contains the middle 50% of the data.",`${n} × 0.5 = ${n/2}`,{js:`${n}*0.5`})}]);
T("stat-sd","a1stat","S.ID.2","Standard deviation",["stat-spread","sqrt-basic"],
 "Standard deviation measures how far values typically sit from the mean. Bigger SD means more spread out.",
 ["Population SD: find the mean, square each deviation, average the squares (variance), then take the square root.","Adding a constant to every value leaves SD unchanged; multiplying every value by k multiplies SD by |k|.","Compare spread: the data set with the larger SD is more spread out."],
 [()=>{let a,v,m,g=0;do{a=Array.from({length:ri(4,5)},()=>ri(1,20));m=a.reduce((x,y)=>x+y)/a.length;v=a.reduce((x,y)=>x+(y-m)**2,0)/a.length;g++}while(g<500&&(!Number.isInteger(m)||v===0||Math.abs(Math.abs(Math.sqrt(v)*100)%1-0.5)<0.05));
     const n=a.length;return mk("num",`Find the population standard deviation of ${a.join(", ")}. (Round to the nearest hundredth.)`,rdn(Math.sqrt(v),2),"Mean → squared deviations → average → square root.",`mean = ${m}; squared deviations sum = ${v*n}; variance = ${rdn(v,3)}; SD ≈ ${rdn(Math.sqrt(v),2)}`,{js:`Math.sqrt([${a}].reduce((s,y)=>s+(y-${m})**2,0)/${n})`,jtol:0.0050001})},
  ()=>{let a,m;do{a=Array.from({length:4},()=>ri(1,20));m=a.reduce((x,y)=>x+y)/4}while(!Number.isInteger(m));const v=a.reduce((x,y)=>x+(y-m)**2,0)/4;return mk("num",`Find the variance (the square of the population standard deviation) of ${a.join(", ")}.`,rdn(v,2),"Variance = average of the squared deviations from the mean.",`mean = ${m}; squared deviations: ${a.map(y=>(y-m)**2).join(", ")}; average = ${rdn(v,2)}`,{js:`[${a}].reduce((s,y)=>s+(y-${m})**2,0)/4`})},
  ()=>{const m=ri(10,40),dA=[ri(1,3),ri(1,3)],dB=[ri(5,9),ri(5,9)];const A=[m-dA[0],m+dA[0],m-dA[1],m+dA[1]],B=[m-dB[0],m+dB[0],m-dB[1],m+dB[1]];return mcq(`Data set A: ${shuffle(A).join(", ")}. Data set B: ${shuffle(B).join(", ")}. Which has the larger standard deviation?`,"Set B",["Set A","They are equal"],"The set whose values are farther from the (common) mean has the larger SD.",`Both have mean ${m}; B's values deviate by at least 5 while A's by at most 3.`)},
  ()=>{const s=ri(2,9),k=ri(2,5);return mk("num",`A data set has standard deviation ${s}. Every value is multiplied by ${k}. What is the new standard deviation?`,s*k,"Multiplying all values by k multiplies the SD by |k|.",`${s} × ${k} = ${s*k}`,{js:`${s}*${k}`})}]);
T("stat-compare","a1stat","S.ID.3","Comparing data sets: outliers, shape & spread",["stat-sd"],
 "Outliers and skew affect the mean more than the median. Compare data sets using a center AND a spread measure that match the shape.",
 ["Skewed right: mean > median.  Skewed left: mean < median.  Symmetric: mean ≈ median.","Outliers pull the mean toward them; the median barely moves, so use the median and IQR for skewed data.","Compare spread with IQR (resistant) or standard deviation."],
 [()=>{const a=Array.from({length:5},()=>ri(10,30));const out=ri(80,150);const m0=a.reduce((x,y)=>x+y)/5,s0=a.slice().sort((x,y)=>x-y)[2];const b=a.concat([out]);const m1=b.reduce((x,y)=>x+y)/6,s1=b.slice().sort((x,y)=>x-y);const med1=(s1[2]+s1[3])/2;const ans=Math.abs(m1-m0)>Math.abs(med1-s0)?"The mean":"The median";return mcq(`The data ${a.join(", ")} gets a new value ${out} added. Which measure of center changes more?`,ans,[ans==="The mean"?"The median":"The mean"],"An outlier pulls the mean strongly; the median is resistant.",`mean: ${rdn(m0,2)} → ${rdn(m1,2)}; median: ${s0} → ${med1}`,{js:`(Math.abs(${m1}-${m0})>Math.abs(${med1}-${s0}))===${ans==="The mean"}`})},
  ()=>{let a,s;let g=0;do{a=Array.from({length:5},()=>ri(5,30));s=a.reduce((x,y)=>x+y)+ri(60,120);g++}while(g<2000&&(a.reduce((x,y)=>x+y)%5!==0||s%6!==0));const out=s-a.reduce((x,y)=>x+y);return mk("num",`The mean of ${a.join(", ")} is ${a.reduce((x,y)=>x+y)/5}. A new value ${out} is added. What is the new mean?`,s/6,"New mean = (old sum + new value) ÷ (count + 1).",`(${a.reduce((x,y)=>x+y)} + ${out})/6 = ${s/6}`,{js:`([${a}].reduce((x,y)=>x+y)+${out})/6`})},
  ()=>{const med=ri(20,60),d=pick([-1,0,1])*ri(4,12);const mean=med+d;const ans=d>0?"Skewed right":d<0?"Skewed left":"Approximately symmetric";return mcq(`A data set has mean ${mean} and median ${med}. What is the most likely shape?`,ans,["Skewed right","Skewed left","Approximately symmetric"].filter(x=>x!==ans),"Mean > median → skewed right; mean < median → skewed left.",`mean − median = ${d}`)},
  ()=>{const a1=ri(5,20),b1=ri(5,20);const iA=ri(4,12);let iB;do{iB=ri(4,12)}while(iB===iA);const ans=iA>iB?"Set A":"Set B";return mcq(`Set A has Q1 = ${a1}, Q3 = ${a1+iA}; Set B has Q1 = ${b1}, Q3 = ${b1+iB}. Which has the greater spread (larger IQR)?`,ans,[ans==="Set A"?"Set B":"Set A"],"IQR = Q3 − Q1: compare them.",`A: ${iA}; B: ${iB}`,{js:`((${a1+iA}-${a1})>(${b1+iB}-${b1}))===${iA>iB}`})}]);
T("stat-reg","a1stat","S.ID.6","Linear regression & correlation",["scatter"],
 "A regression line models the trend in two-variable data. The correlation coefficient r (between −1 and 1) measures how well a line fits and in which direction.",
 ["r near +1: strong positive; near −1: strong negative; near 0: weak or none.","Slope: predicted change in y for 1 unit of x. Intercept: predicted y when x = 0 (may not make sense in context).","Correlation does not prove causation. Predicting outside the data range (extrapolation) is risky."],
 [()=>{const r=pick([0.95,0.88,0.7,0.55,0.15,-0.1,-0.45,-0.7,-0.92,-0.97]);const ans=Math.abs(r)>=0.8?(r>0?"Strong positive":"Strong negative"):Math.abs(r)>=0.5?(r>0?"Moderate positive":"Moderate negative"):"Weak or no linear relationship";return mcq(`A data set has correlation coefficient r = ${r}. How would you describe the linear relationship?`,ans,["Strong positive","Strong negative","Moderate positive","Moderate negative","Weak or no linear relationship"].filter(x=>x!==ans).slice(0,3),"Judge by the size and sign of r.",`|r| = ${Math.abs(r)}`)},
  ()=>{const m=pick([1.5,2,2.5,3,0.5,-1,-2,4]),b=ri(5,40),x=ri(3,15);return mk("num",`The regression line is ŷ = ${m}x + ${b}. Predict y for x = ${x}.`,rdn(m*x+b,3),"Substitute x into the regression equation.",`${m}(${x}) + ${b} = ${rdn(m*x+b,3)}`,{js:`${m}*${x}+${b}`})},
  ()=>{const m=pick([2,3,5,4]),b=ri(5,30),x=ri(2,10),act=m*x+b+rnz(-8,8);return mk("num",`The regression line is ŷ = ${m}x + ${b}. For x = ${x}, the actual value is ${act}. What is the residual (actual − predicted)?`,act-(m*x+b),"Residual = actual − predicted.",`predicted ${m*x+b}; ${act} − ${m*x+b} = ${act-(m*x+b)}`,{js:`${act}-(${m}*${x}+${b})`})},
  ()=>{const m=pick([2,3,5,1.5,2.5]),k=ri(2,6);return mk("num",`A regression line predicts weight (lb) = ${m}·(height in inches) − 90. By how many pounds does it predict weight to change for ${k} more inches of height?`,rdn(m*k,2),"Slope × change in x.",`${m} × ${k} = ${rdn(m*k,2)}`,{js:`${m}*${k}`})}]);
T("sys-word","a1sys","A.CED.3","Systems of equations: word problems",["sys-elim"],
 "Define two variables, write one equation for each relationship in the story, then solve the system (substitution or elimination).",
 ["Let x and y stand for the two unknown quantities; write them down.","One equation usually counts items (x + y = total); the other counts value (price·x + price·y = money).","Check the answer in the original words."],
 [()=>{const x=ri(10,60),y=ri(10,60),p=ri(6,15),q=ri(3,p-1);return mk("pair",`Tickets cost $${p} for adults and $${q} for children. ${x+y} tickets were sold for $${p*x+q*y} total. Find (adults, children).`,`(${x}, ${y})`,"Let x = adults, y = children: x + y = tickets and px + qy = money.",`x + y = ${x+y}; ${p}x + ${q}y = ${p*x+q*y} → x = ${x}, y = ${y}`,{eqs:[`x+y=${x+y}`,`${p}*x+${q}*y=${p*x+q*y}`]})},
  ()=>{const q=ri(3,20),d=ri(3,20);return mk("pair",`A jar has quarters and dimes: ${q+d} coins worth ${25*q+10*d} cents. Find (quarters, dimes).`,`(${q}, ${d})`,"x + y = coins; 25x + 10y = cents.",`x + y = ${q+d}; 25x + 10y = ${25*q+10*d} → x = ${q}, y = ${d}`,{eqs:[`x+y=${q+d}`,`25*x+10*y=${25*q+10*d}`]})},
  ()=>{const x=ri(5,30),k=ri(2,12);return mk("pair",`Two numbers have a sum of ${2*x+k}, and the larger exceeds the smaller by ${k}. Find (larger, smaller).`,`(${x+k}, ${x})`,"Let x = larger, y = smaller: x + y = sum and x − y = difference.",`x + y = ${2*x+k}; x − y = ${k} → x = ${x+k}, y = ${x}`,{eqs:[`x+y=${2*x+k}`,`x-y=${k}`]})}]);
T("sys-ineq","a1ineq","A.REI.12","Systems of linear inequalities",["lin-ineq2","sys-sub"],
 "The solution of a system of inequalities is the overlap of the shaded regions: points satisfying every inequality at once.",
 ["Test each candidate point in every inequality.","Strict inequalities (<, >) exclude boundary points; ≤ and ≥ include them.","The solution region is where all the shadings overlap."],
 [()=>{const m1=rnz(-3,3),b1=ri(-4,4),m2=rnz(-3,3),b2=ri(-4,4),o1=pick([">",">="]),o2=pick(["<","<="]);const test=(x,y)=>(o1===">"?y>m1*x+b1:y>=m1*x+b1)&&(o2==="<"?y<m2*x+b2:y<=m2*x+b2);let pts,k=0;do{pts=distinct(4,-6,6).map(x=>[x,ri(-8,8)]);k++}while(pts.filter(p=>test(p[0],p[1])).length!==1&&k<3000);
     if(pts.filter(p=>test(p[0],p[1])).length!==1)return TOPIC_BY_ID["sys-ineq"].gens[1]();const good=pts.find(p=>test(p[0],p[1]));const s=p=>`(${p[0]}, ${p[1]})`;return mcq(`Which point is a solution of the system y ${o1} ${lin(m1,b1)} and y ${o2} ${lin(m2,b2)}?`,s(good),pts.filter(p=>p!==good).map(s),"Test each point in BOTH inequalities.",`${s(good)} satisfies both; each other point fails at least one.`,{js:`(${good[1]}${o1}${m1*good[0]+b1})&&(${good[1]}${o2}${m2*good[0]+b2})`})},
  ()=>{const c=ri(2,9),d=ri(-5,0),x=ri(-4,8),y=ri(-4,8);const yes=(x+y<=c)&&(x-y>d);return mcq(`Is (${x}, ${y}) a solution of x + y ≤ ${c} and x − y > ${d}?`,yes?"Yes":"No",[yes?"No":"Yes"],"Substitute into both inequalities.",`${x}+${y} = ${x+y} ≤ ${c} is ${x+y<=c}; ${x}−${y} = ${x-y} > ${d} is ${x-y>d}`,{js:`((${x}+${y}<=${c})&&(${x}-${y}>${d}))===${yes}`})},
  ()=>{const m=rnz(-2,3),b=ri(-3,3),c=ri(-3,6);const pts=distinct(5,-5,5).map(x=>[x,ri(-6,8)]);const cnt=pts.filter(p=>p[1]>m*p[0]+b&&p[0]<c).length;return mk("num",`How many of the points ${pts.map(p=>`(${p[0]}, ${p[1]})`).join(", ")} satisfy both y > ${lin(m,b)} and x < ${c}?`,cnt,"Test each point in both inequalities and count those that pass both.",`${cnt} point(s) pass both tests`,{js:`[${pts.map(p=>`[${p}]`)}].filter(p=>p[1]>${m}*p[0]+(${b})&&p[0]<${c}).length`})}]);
